) AS (
  VALUES 
    (122::BIGINT, 'Es bueno explicando, pero es un vulgar, no respeta a sus estudiantes y en general es un hijo de P... es un irrespetuoso y un vulgar. Ahora, explica bien, su clase es aburrida pero es facil de entender y mas facil de pasar, da la oportunidad de hacer los examenes sabados y salir 3 semanas antes.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7598326a6103be9dcc6acd734fe7f258bfce51ad1d214eb529be80abc7474b77'::TEXT, ARRAY[2445]::BIGINT[]),
    (122::BIGINT, 'Si pone atención se aprende mucho, son interesantes. Las evaluaciones no son tan complicadas (dos ensayos, tres exámenes y un trabajo grupal todo virtual), califica bien. Súper recomendado. Da la opción de hacer exámenes sábados y así salir tres semanas antes, pensando en final de semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '8f9e6309a5c174151ea16c400553584a987d13fcfb692f8ffb802534e3c09f9f'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Literal es un curso regalado. Unos ensayos y exámenes virtuales. El profe es buena nota, lleve la materia con él si quiere subir el ponderado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'db06f4288084e6e8d8d9cc35dbf5bda152ce79f7dbed44036cd563b6fc9671e6'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Super facil pasar, literal le regalan el curso. El profe es gracioso y cae bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'e425cf7d89f50c7e07f005e5226fff9b7245f235a6351f3917979a9666fccb6d'::TEXT, ARRAY[2445]::BIGINT[]),
    (122::BIGINT, 'Lleven el curso con él si tienen la oportunidad es excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '147288be2833a626bfc09302f4409b6f5d0d3efa1eb7a44eaaaef81d77f60312'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Eso que dicen que regala el curso, es literal. No reprueba ni aunque lo intente jaja'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-13T00:00:00+00:00'::TIMESTAMPTZ, '71cfc4805f0b01a41d7a844eb9614955144ecbb34158857872f92428412f51ef'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'En general se puede decir que "regala" el curso. Con el simple hecho de ir a clases y hacer los trabajos (que son bastante sencillos) se pasa, las clases son aburridas y el profe es regular en general.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '76691a5e970dbd7fcc510d93ebe298253494881f2face16b3cd639b2047600bd'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Si matrícula con él definitivamente va a pasar demasiado fácil. No le importa la asistencia, las evaluaciones un queque, aunque sí se preocupa por el estudiante. A veces hace unos comentarios un poco fuera de lugar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, '499969926580938ae4620174c9ea4cdaafed3cd205754ae07023f3b1402bca9e'::TEXT, ARRAY[1477]::BIGINT[]),
    (122::BIGINT, 'Bueno en general se pasa muy fácil, habla bastante.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, '3a8294e91f057ca4cb9ddc9956a43d553d6e0e3b230b6ef6af57d095fbbe4108'::TEXT, ARRAY[1477]::BIGINT[]),
    (122::BIGINT, 'Prácticamente nos regalo el curso xd. Si quiere pasar con el SI. Si quiere aprender con el NO.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '809ba4d222af7e0d0f63f07d750dee25bb694d90f0f05c7a62747853d1ba6c03'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Las clases son super largas y aburridas, sin embargo la participación no es obligatoria. Las evaluaciones las califica excelente. Si lo que necesita son créditos aprobados, de fijo con él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, '0973a8be8a0bea1faca2691e0bda8e9831e9c96b5aec866ff5c1527481791b3a'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'No es tan mal hablado como dicen. Los exámenes se pasan fácil con los cuestionarios, solo copiar-pegar, siempre los da antes de los exámenes. Deja pocos ensayos y fáciles. Llevarla virtual es un relajo. Él no es brujo para saber si algo está mal con el estudiante, avísele si algo está mal y ayudará.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c6c9588a90a3f1c8b5dbab370778fdf306540a11dab7da2e1a72f99916955f30'::TEXT, ARRAY[2445]::BIGINT[]),
    (122::BIGINT, 'Hay que ponerle mucha atencion al profe, leer bien las diapositivas y prepararse bien para las practicas, el curso es facil en si pero siempre hay que prepararse un poco porque pone trampas en los examenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-07T00:00:00+00:00'::TIMESTAMPTZ, '9baa92df808dd3146c63f004a60e6f409a20496a702bac1d89ad1dc28eaa659d'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Si se presta atención, se aprende mucho, pero las clases son muy largas y aburridas. Básicamente es escuchar al profe hablar toda la clase. Se pasa muy fácil, pocos trabajos y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '085456db409d0b297d3e1eda45d71726b8b164256d079cb416dbefef15b23896'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Bastante bueno, eso sí las clases son muy largas y a veces tediosas, pero el curso se pasa bastante fácil con él, no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1100845d975090157804a217aed514b4ff1888c7efd8b537ec5c832104b69c68'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Las clases son pesadas por lo largas y es solo escuchar al profe, pero intenta que el curso no sea una carga académica. Tareas y examenes fáciles. El curso como tal es fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0e6a7b2397645f8dfe0a13e3ac1a32f116f043461e00d3882d06370d400861e9'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Calidad de profesor y persona. Es conciente que trabaja con una humanistica y una bastante densa, por eso deja mucho material de apoyo y trata de no sobrecargar a la clase. Fue muy respetuoso en clases, el tiene su personalidad y eso esta bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Inspirador']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'cdc6949989ba938d7f839daea410d1448fdb8420a936c6779dca29420808f850'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Las clases son muuuuuuy largas, y a veces se sale del tema, pero no deja muchos trabajos y las evaluaciones son demasiado faciles, si no pasas el curso con este profe es porque en serio eres demasiado vago, si quieres pasar fácil sin ninguna preocupación matricula con Achoy'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '8f66fff8db8790c67140d3dbb814e5f7c410e30b8339337e38835bf8da44a5cc'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Llevé el curso de relaciones laborales con él. Es un poco machista, hace comentarios un poco fuera de lugar a los estudiantes y utiliza un lenguaje al que él le llama “popular” creo que al que no le moleste ninguna de las cosas anteriores puede disfrutar el curso.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-05T00:00:00+00:00'::TIMESTAMPTZ, '107c9c2ccc5381212cbaff684d1e3e3d5f2bd3a7adf4b53abf7ed5f394309764'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Es muy buen profe, explica lo necesario sin explotar a los estudiantes con tanta materia, pasar el curso es sumamente fácil ya que hasta hace cuestionarios para los exámenes, sin duda volvería a matricular con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '218091dca8dba8b020b7862828f5350fac0ddd5f2c4411cad9544f9ec882a0ca'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Pocos exámenes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '833721ba25d34123273e291d53747fea4bc26dc2aab8d5340e7e8f5db2138bbe'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Es un buen profe, accesible y hace consultas con los estudiantes sobre los aspectos del curso. No hace el curso pesado sino que se enfoca en enseñar lo necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6642236cd25c6b643c523cdd95b563b8213950d1138eb0daaadc8acbe1e20884'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Virtual* El profe es muy buena nota, el curso es super fácil (él hace que no sea un estorbo para la carrera). Ayuda mucho, pocas evaluaciones. Volvería a matricular con él sin duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '592f6f4248b75b489db2152068a3415c39fecf5a3512ce2952165864b6b7cba7'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'No entiendo porqué el profe tiene tan baja calificación. Es demasiado buena nota. Hace que el curso sea un chiste (facilidad), y se preocupa por los estudiantes, (no hace del curso un estorbo). Trabajos y exámenes fáciles. No crean en la calificación que tiene. De fijo volvería a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'fd15d51c90dd00553d541d26ec1ef8ebc949c6a4b3af0cca440c2074f1f3ecc8'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Para ser la primera vez, que da este curso el profe lo abarco bien, se preocupaba por nosotros, se acomodo a nosotros para cuando hacer exámenes, tareas y así, es bueno el profe y se pasa súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ed6643debc103d3686649459986eca43fffb203468510fe2aa8393feee6be2c7'::TEXT, ARRAY[2546]::BIGINT[]),
    (122::BIGINT, 'No entiendo el porqué está mal calificado, el profesor ayuda y explica muy bien. Realmente matricularía de nuevo con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-03-12T00:00:00+00:00'::TIMESTAMPTZ, 'b4cbd744828e055d7d26a6a4b2d5ad3d71673f7cda71c97fb723f078c55c798f'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'No se debería matricular con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '21a9e74d66df5590e4b52303142966ef9a5dee268caacccbce258cd687dc130c'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Pasar el curso es súper fácil, pero casi no se aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'eb9bad8cde3c8c167d3710cf701a0c6ef148f5246f412d416976a64008a92599'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, '5eef06644624260470fb87a4e6cc00e36656b1b764ac8b600f4e55406c6a9e71'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Las clases con él son un poco aburridas, sin embargo, ayuda bastante y hace que el curso sea fácil de pasar, no entiendo por qué tiene una calificación tan baja.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-30T00:00:00+00:00'::TIMESTAMPTZ, '030819bb1f2d28da1cab30b49d2ce41bafafd4ee7ba00d6805dc7d7a6ed30090'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '96d429a7ce565bccbcac58436aadf160ef7b906cd5b25d6561c437f53b7788f5'::TEXT, ARRAY[2445]::BIGINT[]),
    (122::BIGINT, 'Un profe un tanto mediocre para mi gusto. Todo lo da casi que regalado, por no decir que regalado. Todo son puras diapositivas acompañadas de alguna experiencia o ejemplo, no se puede pedir más. No soportaba ver sus faltas ortográficas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '2a0d7fc8a92de5213cb704bd00df0efa0389b51772978e0911cf80c20dfbdc25'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'No explica la materia correctamente, utiliza vocabulario soez y vulgar, da ejemplos de la materia fuera de contexto y se desvía del tema con mucha facilidad. El curso con él es pasable pero no se aprende.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '5d672c44975060fad5ecbad79b8b2c16bcfaccb1cd4d8b1a7553569fa9bd8fb9'::TEXT, ARRAY[2445]::BIGINT[]),
    (122::BIGINT, 'No entiendo cómo este señor es abogado y profesor! CON ÉL NO SE APRENDE NADA pero es obvio que sí va a pasar y más si es mujer.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-31T00:00:00+00:00'::TIMESTAMPTZ, '7cd88067baea56e79a1c85bd9446f10cb4a0ddcf050a49b4dbb23ec4a348e358'::TEXT, ARRAY[2456, 2445]::BIGINT[]),
    (122::BIGINT, 'Es un psicopata sexista. Sacó una navaja en medio de la clase para hacer un ejemplo y "amenazar" a una compañera. Usa palabras como "putifalda", y frases como "las mujeres se exponen", critica a los alumnos por su religión, por quiénes votaron. Temperamento errático. NO DEBERÍA PISAR UN AULA.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '49d724a764f9d8722f387a2f8de5694f1e47aa0f23f5200eb1458773c1d3faa7'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Si ocupa llevar relaciones llévelo con él, da buenos ejemplos, se preocupa porque uno aprenda. Es abogado y le sabe bastante al derecho laboral. Hace 3 exámenes y varios ensayos, pero muy llevadero todo, lo pasé con 95 por vago pudo haber sido un 100 fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-27T00:00:00+00:00'::TIMESTAMPTZ, '9b2f988db7d2a4f9563f5991ef043cc835c9719fd41ffb8a527215d248ba5410'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'El curso es muy llevadero con él, las evaluaciones son sencillas y pocas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'c23aa4cacb7ab2152fc1c3891dd0e01652147251400e685329fe6662331eff15'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '44a8f2558271533e6263a3aea3cb90f9d7c544670a48a4094efee73e1abe5617'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Las clases son largas, pero brinda ejemplos así que no se tornan tan tediosa. Las tareas son sencillas y los exámenes también por lo que, al menos con él, no es un curso complicado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-12-21T00:00:00+00:00'::TIMESTAMPTZ, '5057e916a098fc7b72c2a9feb868051419a0366a7911a4777ca4713459db7110'::TEXT, ARRAY[629]::BIGINT[]),
    (122::BIGINT, 'El curso se pasa súper fácil solo que se aprende muy poco. Si ocupan subir ponderado se los recomiendo full'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c8bab91a6cdb50bb7d0ed83bf9869f6db191f85b04605ec67bd7610627812430'::TEXT, ARRAY[2456]::BIGINT[]),
    (122::BIGINT, 'Para ser la primera vez, que da este curso el profe lo abarco bien, se preocupaba por nosotros, se acomodo a nosotros para cuando hacer exámenes, tareas y así, es bueno el profe y se pasa súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e78a877a019f68c7c12c8cf7b594d148bec235a134135c42822dd49ed07980f7'::TEXT, ARRAY[2546]::BIGINT[]),
    (122::BIGINT, 'Si matricula con él pasa el curso como si nada, pero casi no se aprende. Las clases son aburridas y largas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '11ae9526136f1a50be2d78bc69a0b955b72fbadb54cdaa2fdcc2d136c9e72d1f'::TEXT, ARRAY[2456]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
